<div><div class="flex justify-between mb-6"><div><h1 class="text-2xl font-mono font-bold text-white uppercase">Expenses</h1><p class="text-gray-500">Fast daily expense and settlement control in PKR.</p></div><button wire:click="$set('showExpenseModal',true)" class="bg-primary text-white rounded-lg px-5 py-2">Add Expense</button></div><div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-4 mb-6">@foreach(['Today'=>$today,'Yesterday'=>$yesterday,'Last 7 Days'=>$week,'Last 30 Days'=>$month,'Total'=>$total,'Pending Younus Reimbursement'=>$pending] as $title=>$value)<div class="bg-dark-800 border border-dark-700 rounded-xl p-4"><p class="text-xs text-gray-500">{{$title}}</p><p class="text-xl font-mono text-white">Rs. {{number_format($value,2)}}</p></div>@endforeach</div><div class="mb-6 bg-primary/10 border border-primary/30 rounded-xl p-4 text-primary-light">{{ $partnerNet >= 0 ? 'Bilal owes Usman' : 'Usman owes Bilal' }}: <b>Rs. {{number_format(abs($partnerNet),2)}}</b> <span class="text-gray-400 text-sm">(automatic 50/50 partner split)</span></div><div class="bg-dark-800 rounded-xl overflow-hidden"><table class="w-full"><thead><tr class="text-xs text-gray-400"><th class="p-3 text-left">DATE</th><th class="p-3 text-left">PAID BY</th><th class="p-3 text-left">CATEGORY</th><th class="p-3 text-left">DETAIL</th><th class="p-3 text-right">AMOUNT</th><th class="p-3">STATUS</th></tr></thead><tbody>@forelse($expenses as $expense)<tr class="border-t border-dark-700"><td class="p-3">{{$expense->expense_date->format('d M')}}</td><td class="p-3 capitalize">{{$expense->paid_by}}</td><td class="p-3">{{$expense->category->name}}</td><td class="p-3 text-gray-400">{{$expense->description}}</td><td class="p-3 text-right">Rs. {{number_format($expense->amount)}}</td><td class="p-3">@if($expense->reimbursement_status==='pending')<button wire:click="clear({{$expense->id}})" class="text-amber-300">Pending — Clear</button>@else<span class="text-emerald-300">{{$expense->reimbursement_status==='cleared'?'Cleared':'—'}}</span>@endif</td></tr>@empty<tr><td colspan="6" class="p-8 text-center text-gray-500">No expenses yet.</td></tr>@endforelse</tbody></table></div>@if($showExpenseModal)<div class="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4"><form wire:submit="saveExpense" class="w-full max-w-lg bg-dark-800 rounded-xl p-6 space-y-4"><h2 class="text-white text-lg">Add Expense</h2><div><select wire:model="expense_category_id" class="w-full bg-dark-700 p-3 text-white"><option value="">Select category</option>@foreach($categories as $c)<option value="{{$c->id}}">{{$c->name}}</option>@endforeach</select><button type="button" wire:click="$set('showCategoryModal',true)" class="text-primary-light text-sm mt-2">+ Add Category</button></div><div class="grid grid-cols-2 gap-3"><input type="date" wire:model="expense_date" class="bg-dark-700 p-3 text-white"><input type="number" wire:model="amount" placeholder="Amount (PKR)" class="bg-dark-700 p-3 text-white"></div><select wire:model="paid_by" class="w-full bg-dark-700 p-3 text-white"><option value="younus">Younus (out of pocket)</option><option value="usman">Usman</option><option value="bilal">Bilal Bhatti</option></select><input wire:model="description" placeholder="What was it for?" class="w-full bg-dark-700 p-3 text-white"><textarea wire:model="notes" placeholder="Optional note" class="w-full bg-dark-700 p-3 text-white"></textarea><div class="flex gap-3"><button class="bg-primary text-white px-5 py-2 rounded">Save</button><button type="button" wire:click="$set('showExpenseModal',false)" class="text-gray-400">Cancel</button></div></form></div>@endif@if($showCategoryModal)<div class="fixed inset-0 bg-black/80 z-[60] flex items-center justify-center"><div class="bg-dark-800 p-6 rounded-xl"><input wire:model="category_name" placeholder="New category" class="bg-dark-700 p-3 text-white"><button wire:click="addCategory" class="bg-primary text-white p-3 ml-2">Save</button></div></div>@endif</div>
